sql.where:
AND mall_order_info.`del_flag` = '0'
AND mall_order_info.`is_pay` = '1'
AND mall_order_info.`status` IN ('1', '2', '3')

	AND mall_order_info.`order_no` LIKE CONCAT('%', #{query.orderNo}, '%')


	AND mall_order_info.`status` = #{query.status}


	AND COALESCE(mall_order_info.`wx_shipping_status`, '0') = #{query.wxShippingStatus}


	AND (
		mall_order_info.`order_no` LIKE CONCAT('%', #{query.shippingKeyword}, '%')
		OR mall_order_info.`transaction_id` LIKE CONCAT('%', #{query.shippingKeyword}, '%')
		OR mall_user.`user_no` LIKE CONCAT('%', #{query.shippingKeyword}, '%')
		OR mall_user.`nick_name` LIKE CONCAT('%', #{query.shippingKeyword}, '%')
		OR mall_user.`mobile` LIKE CONCAT('%', #{query.shippingKeyword}, '%')
		OR mall_order_logistics.`logistics_no` LIKE CONCAT('%', #{query.shippingKeyword}, '%')
	)


	AND mall_order_info.`payment_time` >= #{query.beginTime}


	AND mall_order_info.`payment_time` <= #{query.endTime}

